49	/**
50	 * Regex patterns for Claude Code slash command XML tags in user message content.
51	 * These are emitted by the Claude Code CLI when the user runs a local command
52	 * (e.g., /compact, /init). The messages contain structured XML tags:
53	 *   - <command-name>/compact</command-name>
54	 *   - <command-message>compact</command-message>
55	 *   - <command-args>...</command-args>
56	 *   - <local-command-stdout>...</local-command-stdout>
57	 */
58	const COMMAND_NAME_PATTERN = /<command-name>([\s\S]*?)<\/command-name>/;
59	const COMMAND_STDOUT_PATTERN = /<local-command-stdout>([\s\S]*?)<\/local-command-stdout>/;
60	
61	/**
62	 * Scans user message contents for slash command patterns and extracts
63	 * the command name and optional stdout output.
64	 *
65	 * Returns undefined if no command patterns are found.
66	 */
67	function extractCommandInfo(contents: readonly (string | ContentBlock[])[]): { commandName: string; stdout?: string } | undefined {
68		let commandName: string | undefined;
69		let stdout: string | undefined;
70	
71		for (const content of contents) {
72			if (typeof content === 'string') {
73				const nameMatch = COMMAND_NAME_PATTERN.exec(content);
74				if (nameMatch) {
75					commandName ??= nameMatch[1].trim();
76				}
77				const stdoutMatch = COMMAND_STDOUT_PATTERN.exec(content);
78				if (stdoutMatch) {
79					stdout ??= stdoutMatch[1].trim();
80				}
81			} else {
82				for (const block of content) {
83					if (isTextBlock(block)) {
84						const nameMatch = COMMAND_NAME_PATTERN.exec(block.text);
85						if (nameMatch) {
86							commandName ??= nameMatch[1].trim();
87						}
88						const stdoutMatch = COMMAND_STDOUT_PATTERN.exec(block.text);
89						if (stdoutMatch) {
90							stdout ??= stdoutMatch[1].trim();
91						}
92					}
93				}
94			}
95		}
96	
97		if (commandName !== undefined) {
98			return { commandName, stdout };
99		}
100		return undefined;
101	}
